assert round(_fin.FV(0.0025, 48, -1000, 0), 2) == 50931.21
assert round(_fin.FV(0.004, 36, -2000, -100000), 2) == 192731.46
assert round(_fin.FV(0.01, 24, 0, -_fin.FV(0.01, 12, -100, 0)), 2) == 1610.34
_ib = _fin.FV(0.004, 24, 0, -_fin.FV(0.012, 12, 0, -_fin.FV(0.04, 2, 0, -60000)))
assert round(_ib, 2) == 82412.52 and round(_fin.FV(0.05, 7, 0, -60000), 2) == 84426.03
_ny = _fin.FV(0.06, 3, 0, -_fin.FV(0.025, 6, 0, 250000))
assert round(_ny, 2) == -345303.35 and round(_fin.FV(0.055, 6, 0, 250000), 2) == -344710.70

